{
  "scripts": [
    {
      "topic_id": "ilk-yil-bal",
      "title": "Bir yaşından önce bal neden verilmez?",
      "age_group": "12 aydan küçük bebekler",
      "hooks": [
        {
          "kind": "daily",
          "text": "Bebeğinizin mamasını tatlandırmak için ufak bir kaşık bal vermeyi düşünebilirsiniz."
        },
        {
          "kind": "myth",
          "text": "Bir yaşından küçük bebeklere bal yedirmek güvenli değildir ve bebek botulizmi riskine yol açabilir."
        },
        {
          "kind": "question",
          "text": "Bir yaşından küçük bebeklere neden asla bal verilmemelidir?"
        }
      ],
      "selected_hook": 0,
      "selection_reason": "Günlük hayatta sık karşılaşılan tatlandırma eğilimini ele alarak doğrudan uyarıda bulunur.",
      "cta": "Bu videoyu kaydedin.",
      "social_copy": {
        "reels": {
          "title": "Bebeklere Bal Ne Zaman Verilir?",
          "caption": "Bir yaşından küçük bebeklere bal vermek ciddi bir gıda zehirlenmesi olan botulizme yol açabilir. Bu önemli bilgiyi sevdiklerinizle paylaşın.",
          "hashtags": [
            "#ÇocukSağlığı",
            "#BebekBeslenmesi",
            "#DoktorTavsiyesi",
            "#DrMustafaBurakSeven"
          ]
        },
        "youtube_shorts": {
          "title": "Bebeklere Neden Bal Verilmez?",
          "description": "Bir yaşından küçük bebeklere bal verilmemelidir. Bal, bebeklerde ciddi bir gıda zehirlenmesi olan botulizme neden olabilir. Detaylar videomda.",
          "hashtags": [
            "#Shorts",
            "#BebekBeslenmesi",
            "#ÇocukSağlığı",
            "#DrMustafaBurakSeven"
          ]
        }
      },
      "sources": [
        "https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/foods-and-drinks-to-avoid-or-limit.html"
      ],
      "broll": [
        {
          "screen_text": "Bebek Beslenmesi",
          "visual": "Kamera dışındaki bir kadının endişeli bir ses tonuyla bebek mamasına bal eklenip eklenemeyeceğini sorması.",
          "motion_prompt": "A medium shot of an off-camera woman asking a question with a concerned expression in a warm pediatric clinic setting."
        },
        {
          "screen_text": "Doktor Yanıtı",
          "visual": "Doktor Mustafa Burak Seven'in sakin bir ifadeyle kameraya dönerek yanıt vermeye başlaması.",
          "motion_prompt": "A close-up of Dr. Mustafa Burak Seven sitting calmly in his office, listening and beginning to answer directly to the camera."
        },
        {
          "screen_text": "Bir Yaşından Önce Bal",
          "visual": "Mutfak tezgahında duran bir kavanoz bal ve yanında bebek kaşığı.",
          "motion_prompt": "A static macro shot of a honey jar sitting on a clean kitchen counter next to a small infant spoon."
        },
        {
          "screen_text": "Botulizm Riski",
          "visual": "Bir annenin elinde bebek maması kasesiyle dikkatlice masaya yaklaştığı an.",
          "motion_prompt": "A steady portrait shot of a mother carefully preparing a baby bowl at a wooden dining table."
        },
        {
          "screen_text": "12 Aydan Küçükler",
          "visual": "Bebeğin mamasına bal karıştırılmasının engellendiğini gösteren yakın plan el hareketi.",
          "motion_prompt": "A close-up of hands moving a honey jar away from a baby formula bowl safely."
        },
        {
          "screen_text": "Güvenli Gıdalar",
          "visual": "Doktorun masasında duran bilgilendirme broşürleri ve stetoskop.",
          "motion_prompt": "A clean, warm-toned view of a pediatrician desk with a stethoscope and medical notes."
        },
        {
          "screen_text": "Gıda Zehirlenmesi",
          "visual": "Bir annenin bebeğinin mamasını sade su ve formül ile hazırlaması.",
          "motion_prompt": "A gentle side-angle shot of a mother preparing safe infant food without any added sweeteners."
        },
        {
          "screen_text": "Ağız ve Sindirim",
          "visual": "Bebeğin güvenli bir şekilde kendi kaşığıyla püre türü gıdalar yemesi.",
          "motion_prompt": "A close-up of a baby holding a safe feeding spoon at a high chair during daytime."
        },
        {
          "screen_text": "Uzman Uyarısı",
          "visual": "Doktor Mustafa Burak Seven'in hafifçe öne doğru eğilerek önemli bir detayı vurgulaması.",
          "motion_prompt": "A steady medium shot of the doctor calmly emphasizing a vital health warning in his office."
        },
        {
          "screen_text": "Su ve Formül",
          "visual": "Biberon içerisindeki güvenli bebek sütü veya suyun yakından görünümü.",
          "motion_prompt": "A clear, well-lit shot of a standard baby bottle filled with safe liquid on a clean table."
        },
        {
          "screen_text": "Bebek Sağlığı",
          "visual": "Annenin bebeğini kucağına alarak güvenli beslenme hakkında bilgi okuması.",
          "motion_prompt": "A soft focus view of a mother holding her healthy baby while checking infant nutrition guidelines."
        },
        {
          "screen_text": "Önemli Kural",
          "visual": "Doktor Mustafa Burak Seven'in ellerini masada kavuşturarak konuşmasını sürdürmesi.",
          "motion_prompt": "A steady portrait shot of the doctor speaking calmly with clasped hands on his desk."
        },
        {
          "screen_text": "Videoyu Kaydedin",
          "visual": "Doktor Mustafa Burak Seven'in sakin ve güven veren yüz ifadesiyle videoyu tamamlaması.",
          "motion_prompt": "A closing portrait shot of Dr. Mustafa Burak Seven delivering the final practical message smoothly."
        }
      ],
      "speech_sections": {
        "intro": "Hocam, bebeğimin mamasını tatlandırmak için azıcık bal verebilir miyim? Hayır, bir yaşından küçük bebeklere asla bal verilmemelidir.",
        "body": "Bebeklere bir yaşından önce bal verilmesi, infant botulizm adı verilen çok ciddi bir gıda zehirlenmesine yol açabilir. Bu nedenle balı bebeğinizin yiyeceklerine, suyuna, formül mamasına veya emziğine kesinlikle eklememelisiniz. Sindirim sistemi henüz yeterince gelişmemiş olan bu dönemdeki bebekler için bal güvenli değildir. Sağlıklı bir gelişim ve güvenli bir beslenme süreci için bir yaşına kadar bu kurala mutlaka dikkat etmeliyiz.",
        "outro": "Bebeğinizin sağlığını korumak adına bu tür riskli gıdalardan kaçınmak en doğru adımdır. Bu videoyu kaydedin."
      }
    },
    {
      "topic_id": "tokluk-isaretleri",
      "title": "Bebeğim başını çevirince ne yapmalıyım?",
      "age_group": "6–24 ay",
      "hooks": [
        {
          "kind": "daily",
          "text": "Bebeğiniz yemek sırasında birden başını öteye çevirdiğinde ne anlama geldiğini merak edebilirsiniz."
        },
        {
          "kind": "myth",
          "text": "Bebeğin tabağındaki her şeyi bitirmesi gerektiği inancı yanlıştır; bebekler ne kadar yiyeceklerine kendileri karar verir."
        },
        {
          "kind": "question",
          "text": "Bebeğiniz yemek yerken başını çevirdiğinde veya mamayı ittiğinde ne yapmalısınız?"
        }
      ],
      "selected_hook": 0,
      "selection_reason": "Annelerin sıklıkla yaşadığı beslenme anındaki tepkileri doğrudan ele alır.",
      "cta": "Bu videoyu kaydedin.",
      "social_copy": {
        "reels": {
          "title": "Bebeğim Başını Çevirince Ne Yapmalıyım?",
          "caption": "Bebeğiniz yemek sırasında başını çeviriyor veya tabağı itiyorsa doymuş olabilir. Onu yemek için zorlamayın.",
          "hashtags": [
            "#ÇocukSağlığı",
            "#EkGıda",
            "#BebekBeslenmesi",
            "#DrMustafaBurakSeven"
          ]
        },
        "youtube_shorts": {
          "title": "Bebeğim Yemekte Başını Çeviriyor",
          "description": "Bebeğiniz başını çevirdiğinde veya ağzını kapattığında bu tokluk işaretidir. Yemeği bitirmesi için asla zorlamayın.",
          "hashtags": [
            "#Shorts",
            "#EkGıda",
            "#BebekBeslenmesi",
            "#DrMustafaBurakSeven"
          ]
        }
      },
      "sources": [
        "https://www.cdc.gov/infant-toddler-nutrition/mealtime/signs-your-child-is-hungry-or-full.html"
      ],
      "broll": [
        {
          "screen_text": "Tokluk İşaretleri",
          "visual": "Kamera dışındaki bir annenin bebek beslerken yaşadığı kararsızlığı sorması.",
          "motion_prompt": "A medium shot of an off-camera mother asking a practical question about infant feeding cues in a clinic."
        },
        {
          "screen_text": "Doktor Yanıtı",
          "visual": "Doktor Mustafa Burak Seven'in hastane odasında sakince dinleyip açıklamaya başlaması.",
          "motion_prompt": "A close-up portrait of Dr. Mustafa Burak Seven calmly listening and starting to explain the response."
        },
        {
          "screen_text": "Başını Çevirme",
          "visual": "6-24 ay arası bir bebeğin mama sandalyesinde oturduğu an.",
          "motion_prompt": "A steady portrait shot of an infant sitting safely in a high chair during mealtime."
        },
        {
          "screen_text": "Tokluk Çıkarımları",
          "visual": "Bebeğin kaşığa karşı başını başka yöne çevirmesini simgeleyen yakın plan görünüm.",
          "motion_prompt": "A close-up view of a child gently turning their head away from an offered spoon of food."
        },
        {
          "screen_text": "Ağzını Kapatmak",
          "visual": "Bir annenin bebeğinin yemek saatindeki tepkilerini dikkatle gözlemlemesi.",
          "motion_prompt": "A warm, steady shot of a mother observing her baby's feeding responses attentively."
        },
        {
          "screen_text": "Yemeği İtmek",
          "visual": "Bebeğin küçük elleriyle önündeki mama kasesini hafifçe uzaklaştırması.",
          "motion_prompt": "A close-up of a baby's hands gently pushing a feeding bowl away on the high chair tray."
        },
        {
          "screen_text": "Kendi Kararı",
          "visual": "Doktor Mustafa Burak Seven'in ellerini masada birleştirerek açıklamayı sürdürmesi.",
          "motion_prompt": "A steady medium shot of the doctor speaking calmly and explaining infant autonomy."
        },
        {
          "screen_text": "Zorlamayın",
          "visual": "Mama sandalyesinde oturan bebeğin sakin ve huzurlu bir şekilde etrafa bakması.",
          "motion_prompt": "A gentle close-up shot of a well-fed baby sitting calmly in a high chair."
        },
        {
          "screen_text": "Uzman Önerisi",
          "visual": "Doktorun masası üzerinde duran sağlıklı beslenme kılavuzu ve bardak.",
          "motion_prompt": "A clean, professional macro shot of a pediatric guide on a wooden desk."
        },
        {
          "screen_text": "Tabağı Bitirmek",
          "visual": "Annenin bebeği yemek yemesi için zorlamadan kaşığı masaya bırakması.",
          "motion_prompt": "A soft-focus view of a mother respecting her child's fullness cues during mealtime."
        },
        {
          "screen_text": "Sesli ve El Hareketleri",
          "visual": "Bebeğin yemek istemediğini belirten el hareketleri yapmasını simgeleyen detay.",
          "motion_prompt": "A close-up of a baby's hands resting quietly on the high chair tray after eating."
        },
        {
          "screen_text": "Huzurlu Öğün",
          "visual": "Doktor Mustafa Burak Seven'in sakin bir tebessümle konuşmasını sürdürmesi.",
          "motion_prompt": "A steady portrait shot of the doctor speaking with an encouraging expression."
        },
        {
          "screen_text": "Videoyu Kaydedin",
          "visual": "Doktor Mustafa Burak Seven'in videoyu huzurlu bir kapanışla tamamlaması.",
          "motion_prompt": "A closing portrait shot of Dr. Mustafa Burak Seven delivering the final call to action."
        }
      ],
      "speech_sections": {
        "intro": "Hocam, bebeğim yemek sırasında başını çevirirse ne yapmalıyım? Başını çeviriyorsa doymuş olabilir, onu zorlamamalısınız.",
        "body": "Altı ile yirmi dört aylık bebekler, henüz konuşamasalar bile doyduklarını beden dilleriyle belli ederler. Bebeğiniz yemek sırasında başını food yani yiyeceklerden başka yöne çeviriyorsa, ağzını kapatıyorsa, yemeği itiyorsa veya ses çıkararak doyduğunu belirtiyorsa ona saygı duymalısınız. Çocuğunuzun tabağındaki her şeyi bitirmesi gerekmez; ne kadar yemek isteyeceğine kendisinin karar vermesine izin verin. Yemek hiçbir zaman ödül veya ceza olarak kullanılmamalıdır.",
        "outro": "Bebeğinizin tok olduğunu gösteren bu işaretleri izleyerek huzurlu bir beslenme rutini oluşturabilirsiniz. Bu videoyu kaydedin."
      }
    },
    {
      "topic_id": "ek-gidada-doku",
      "title": "Püreden farklı dokulara ne zaman geçilir?",
      "age_group": "Ek gıdaya başlamış bebekler",
      "hooks": [
        {
          "kind": "daily",
          "text": "Sürekli püre vermekten sıkıldıysanız bebeğinizin farklı dokuları deneme zamanı gelmiş olabilir."
        },
        {
          "kind": "myth",
          "text": "Bebeğin pürelerden pütürlü ve katı dokulara geçişi tek bir günde anica yapılmalıdır inanışı yanlıştır."
        },
        {
          "kind": "question",
          "text": "Püreden farklı ve pütürlü gıda dokularına ne zaman ve nasıl geçilmelidir?"
        }
      ],
      "selected_hook": 0,
      "selection_reason": "Püre döneminden sonraki doğal geçiş sürecini günlük bir gözlemle başlatır.",
      "cta": "Bu videoyu kaydedin.",
      "social_copy": {
        "reels": {
          "title": "Ek Gıdada Püreden Farklı Dokulara Geçiş",
          "caption": "Bebeğinizin çiğneme gelişimi arttıkça pürelerden pütürlü dokulara geçebilirsiniz. Sert parça ve tehlikelerden kaçının.",
          "hashtags": [
            "#ÇocukSağlığı",
            "#EkGıda",
            "#BebekBeslenmesi",
            "#DrMustafaBurakSeven"
          ]
        },
        "youtube_shorts": {
          "title": "Püreden Pütürlü Gıdaya Geçiş Rehberi",
          "description": "Bebeğinizin gelişimine uygun olarak pürelerden daha pütürlü dokulara kademeli geçiş yapabilirsiniz. Boğulma risklerine dikkat edin.",
          "hashtags": [
            "#Shorts",
            "#EkGıda",
            "#BebekBeslenmesi",
            "#DrMustafaBurakSeven"
          ]
        }
      },
      "sources": [
        "https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/when-what-and-how-to-introduce-solid-foods.html",
        "https://www.cdc.gov/infant-toddler-nutrition/foods-and-drinks/choking-hazards.html"
      ],
      "broll": [
        {
          "screen_text": "Ek Gıdada Doku",
          "visual": "Kamera dışındaki bir babanın püre sonrası dokularla ilgili soru sorması.",
          "motion_prompt": "A medium shot of an off-camera father asking a pediatric question in the office."
        },
        {
          "screen_text": "Doktor Yanıtı",
          "visual": "Doktor Mustafa Burak Seven'in dikkatle dinleyip hafifçe başını sallayarak yanıt vermesi.",
          "motion_prompt": "A close-up portrait of Dr. Mustafa Burak Seven nodding and starting to answer the question."
        },
        {
          "screen_text": "Püre Kıvamı",
          "visual": "Bir kaşık dolusu pürüzsüz bebek mamasının yakından çekimi.",
          "motion_prompt": "A macro close-up of smooth, pureed infant food on a clean spoon."
        },
        {
          "screen_text": "Gelişime Uygun Doku",
          "visual": "Bebeğin mama sandalyesinde güvenli bir şekilde otururken ki görünümü.",
          "motion_prompt": "A steady portrait shot of a baby sitting safely in a high chair during feeding."
        },
        {
          "screen_text": "Pütürlü Gıdalar",
          "visual": "Çatalla ezilmiş yumuşak sebze parçalarının tabaktaki görüntüsü.",
          "motion_prompt": "A close-up shot of softly cooked vegetables mashed gently with a fork on a plate."
        },
        {
          "screen_text": "Çiğneme Becerisi",
          "visual": "Bebeğin elinde tuttuğu yumuşak gıdayı ağzına götürmeye çalışması.",
          "motion_prompt": "A close-up view of a baby's hands exploring soft food texture at the high chair."
        },
        {
          "screen_text": "Boğulma Tehlikesi",
          "visual": "Doktor Mustafa Burak Seven'in ellerini birleştirerek uyarıda bulunması.",
          "motion_prompt": "A steady medium shot of the doctor emphasizing safe food preparation clearly."
        },
        {
          "screen_text": "Sert Parçalar",
          "visual": "Çiğnenmesi zor sert meyve dilimlerinin masadan uzaklaştırılması.",
          "motion_prompt": "A close-up shot of hard raw food pieces being removed from a child's feeding area."
        },
        {
          "screen_text": "Doğru Hazırlık",
          "visual": "Annenin sebzeleri çatal kolaylığında ezerek hazırlaması.",
          "motion_prompt": "A warm-toned macro shot of cooked fruits and vegetables being mashed until soft."
        },
        {
          "screen_text": "Gözetim Altında",
          "visual": "Bebeğin yemek sırasında güvenli bir şekilde ebeveyni tarafından izlenmesi.",
          "motion_prompt": "A steady portrait view of a mother watching her baby eat safely without distractions."
        },
        {
          "screen_text": "Uygun Porsiyon",
          "visual": "Küçük porsiyonlar halinde hazırlanmış yumuşak kıvamlı bebek öğünü.",
          "motion_prompt": "A clear, well-lit shot of small, safe food portions on a baby plate."
        },
        {
          "screen_text": "Güvenli Adımlar",
          "visual": "Doktor Mustafa Burak Seven'in güven veren yüz ifadesiyle konuşmaya devam etmesi.",
          "motion_prompt": "A steady portrait shot of the doctor speaking calmly with professional warmth."
        },
        {
          "screen_text": "Videoyu Kaydedin",
          "visual": "Doktor Mustafa Burak Seven'in sakin bir kapanış pozuyla videoyu bitirmesi.",
          "motion_prompt": "A closing portrait shot of Dr. Mustafa Burak Seven completing the practical guide."
        }
      ],
      "speech_sections": {
        "intro": "Hocam, püreden farklı dokulara ne zaman geçilir? Bebeğinizin çiğneme becerisi geliştikçe daha kalın ve pütürlü dokulara geçebilirsiniz.",
        "body": "Başlangıçta püre kıvamında pürüzsüz gıdalarla başlasanız da, bebeğiniz büyüdükçe dokuları kademeli olarak kalınlaştırabilirsiniz. Bebeğiniz yeni dokulara alışırken öksürebilir, öğürebilir veya tükürebilir; bu gayet normaldir. Çatalla kolayca ezilebilecek yumuşaklıkta pişmiş sebze ve meyveler sunarak çiğneme kaslarını destekleyebilirsiniz. Ancak sert, küçük ve yapışkan gıdaların boğulma riski taşıdığını unutmayın ve her zaman bebeğinizi yemek yerken yakından gözetim altında tutun.",
        "outro": "Bebeğinizin gelişimine uygun dokular seçerek güvenli bir geçiş sağlayabilirsiniz. Bu videoyu kaydedin."
      }
    }
  ]
